public class Planets {

    public enum Planet {
        MERCURY(3.7),
        EARTH(9.81),
        MARS(3.71);

        private final double surfaceGravity;

        Planet(double surfaceGravity) {
            this.surfaceGravity = surfaceGravity;
        }

        public double getSurfaceGravity() {
            return surfaceGravity;
        }
    }

    public static double weightOn(Planet p, double weightOnEarthNewtons) {
        return weightOnEarthNewtons / Planet.EARTH.getSurfaceGravity() * p.getSurfaceGravity();
    }
}
